'use strict';
// Extracted from the latest verified single-file LuMaCo prototype.
function renderDashboard(){const op=state.promises.filter(p=>p.status==='Open').sort((a,b)=>a.due.localeCompare(b.due));const urgent=op.filter(p=>dayDiff(p.due)<=1);const reply=state.messages.filter(m=>m.tracked&&m.action==='Needs Reply'&&m.priority==='High');const d=state.drafts.filter(x=>x.status==='Pending');const attention=[...urgent.slice(0,2).map(p=>({title:p.title,detail:`${company(p.companyId)?.name||''} · ${contact(p.contactId)?.name||''}`,why:dueText(p.due),kind:'promise',id:p.id})),...reply.slice(0,2).map(m=>({title:m.subject,detail:`${company(m.companyId)?.name||''} · ${m.sender}`,why:'Needs reply',kind:'mail',id:m.id})),...d.slice(0,1).map(x=>({title:'Review call or meeting notes',detail:x.company+' · Unfiled draft',why:'Review',kind:'draft',id:x.id}))].slice(0,5);const tracked=state.contacts.length;const detail=state.contacts.filter(detailed).length;const overdue=op.filter(p=>dayDiff(p.due)<0).length;let allm=state.messages;let nReply=allm.filter(m=>m.action==='Needs Reply').length;let now=new Date();return `<div class="hero"><div class="hero-inner"><div><div class="eyebrow">Personal workspace · Relationship intelligence</div><h1>Good ${now.getHours()<12?'morning':now.getHours()<17?'afternoon':'evening'}.</h1><p>Your important conversations, open commitments, and next steps — without manually updating a CRM.</p></div><div class="hero-date">${icon('calendar')} ${now.toLocaleDateString('en-US',{weekday:'short',month:'long',day:'numeric'})}</div></div></div><div class="dashboard-priority-stack"><section class="card pad">${section(`${icon('alert')} Needs Attention`,'View follow-ups','go-followups')}<div class="small muted" style="margin:-7px 0 14px">Highest-priority items come first, not generic metrics.</div>${attention.length?attention.map(x=>`<div class="item-row"><div class="row-icon ${x.kind==='promise'?'warn':''}">${icon(x.kind==='promise'?'clipboard':x.kind==='mail'?'mail':'file')}</div><div class="row-main"><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p><div class="row-meta"><span class="pill ${x.kind==='promise'?'danger':'gold'}">${esc(x.why)}</span></div></div><button class="row-arrow" data-open-${x.kind}="${x.id}" aria-label="Open item">${icon('arrow')}</button></div>`).join(''):itemEmpty('Nothing urgent in your tracked relationships.')}</section><section class="card pad">${section(`${icon('clipboard')} Open Promises`,'View all','go-promises')}<div class="small muted" style="margin:-7px 0 13px">What you committed to — and what others committed to you.</div>${op.slice(0,4).map(p=>`<div class="item-row"><div class="row-icon">${icon('check')}</div><div class="row-main"><strong>${esc(p.title)}</strong><p><b class="company-name">${esc(company(p.companyId)?.name||'Unassigned')}</b> · ${esc(p.owner)}</p><div class="row-meta">${promisePill(p)}<span class="small muted">${esc(p.direction)}</span></div></div><button class="row-arrow" data-open-promise="${p.id}" aria-label="Open promise">${icon('arrow')}</button></div>`).join('')||itemEmpty('No open commitments detected.')}</section></div><section class="gap-section">${section(`${icon('mail')} Smart Email`,'Open Smart Email','go-inbox')}<div class="grid g4">${[{name:'Needs reply',count:nReply,fil:'Needs Reply',ico:'mail'},{name:'Customer emails',count:allm.filter(x=>x.category==='External').length,fil:'External',ico:'users'},{name:'Internal',count:allm.filter(x=>x.category==='Internal').length,fil:'Internal',ico:'building'},{name:'Vendors',count:allm.filter(x=>x.category==='Vendors').length,fil:'Vendors',ico:'briefcase'}].map(s=>`<button class="card summary-stat" style="text-align:left;cursor:pointer" data-email-filter="${s.fil}"><div class="stat-icon">${icon(s.ico)}</div><strong>${s.count}</strong><span>${s.name}</span></button>`).join('')}</div><p class="small muted" style="margin-top:10px">All inbox emails can be sorted. Only explicitly approved LuMaCo contacts enter relationship tracking and Open Promises.</p></section><div class="split gap-section"><section class="card pad">${section(`${icon('calendar')} Upcoming Follow-ups`,'See all','go-followups')}${state.contacts.filter(c=>c.cadence).sort((a,b)=>nextFollow(a).localeCompare(nextFollow(b))).slice(0,4).map(c=>`<div class="item-row"><div class="row-icon">${icon('calendar')}</div><div class="row-main"><strong>${esc(c.name)}</strong><p>${esc(company(c.companyId)?.name||'No company')} · ${esc(c.cadence+'-day cadence')}</p><div class="row-meta"><span class="pill ${dayDiff(nextFollow(c))<0?'danger':'neutral'}">${dueText(nextFollow(c))}</span></div></div><button class="row-arrow" data-open-contact="${c.id}">${icon('arrow')}</button></div>`).join('')}</section><section class="card pad">${section(`${icon('star')} Key Relationships`,'View contacts','go-contacts')}${state.contacts.filter(detailed).slice(0,4).map(c=>`<div class="item-row"><div class="avatar">${initials(c.name)}</div><div class="row-main"><strong>${esc(c.name)} ${c.starred?`<span style="color:var(--gold)">${icon('star','sm')}</span>`:''}</strong><p><b class="company-name">${esc(company(c.companyId)?.name||'')}</b> · ${esc(c.title)}</p><div class="row-meta"><span class="pill gold">Detailed report</span><span class="pill neutral">${esc(c.priority)} priority</span></div></div><button class="row-arrow" data-open-contact="${c.id}">${icon('arrow')}</button></div>`).join('')}</section></div><div class="gap-section">${section(`${icon('sparkle')} See the automation in action`)}<div class="grid g4">${[['mail','Incoming email','See sorting, automatic promise detection and contact history.','simulate-email'],['message','Incoming text','See a permitted text touchpoint matched to an approved customer.','simulate-text'],['phone','Completed customer call','See the immediate prompt, auto-filled metadata and review flow.','simulate-call'],['mic','Meeting ends','Choose meeting capture or verbal recap; review and file text.','simulate-meeting']].map(([i,t,d,a])=>`<div class="card pad"><div class="row-icon" style="margin-bottom:13px;color:var(--gold)">${icon(i)}</div><h3 style="font-size:15px;color:var(--navy)">${t}</h3><p class="muted small" style="margin:7px 0 15px;min-height:40px">${d}</p>${button('Run simulated workflow '+icon('arrow','sm'),a,'sm')}</div>`).join('')}</div></div><div class="gap-section grid g4">${[['Tracked contacts',tracked,'users'],['Detailed relationships',detail,'star'],['Open promises',op.length,'clipboard'],['Overdue promises',overdue,'alert']].map(([a,n,i])=>`<div class="card summary-stat" style="display:flex;align-items:center;gap:12px"><div class="stat-icon" style="margin:0">${icon(i)}</div><div><strong style="font-size:19px">${n}</strong><span>${a}</span></div></div>`).join('')}</div>`}
function renderInbox(){const actionOptions=['All','Needs Reply','Open Promise','Waiting','FYI'];const categoryOptions=['All','External','Internal','Vendors','Personal'];let mails=state.messages.filter(m=>(ui.mailCategory==='All'||m.category===ui.mailCategory)&&(ui.mailAction==='All'||m.action===ui.mailAction)&&(!ui.mailSearch||`${m.sender} ${m.subject} ${m.preview} ${company(m.companyId)?.name||''}`.toLowerCase().includes(ui.mailSearch.toLowerCase())));let chosen=state.messages.find(m=>m.id===ui.selectedMail)||mails[0];if(chosen&&!mails.includes(chosen))chosen=mails[0];let p=chosen&&state.promises.find(p=>p.sourceId===chosen.id&&p.status==='Open');return `${head('Communication intelligence','Smart Email','Every email is sorted. Only explicitly approved contacts are tracked in relationship records.',button(icon('sparkle')+' Simulate incoming email','simulate-email','gold'))}<div class="notice" style="margin-bottom:18px"><strong>Two independent classifications:</strong> relationship category (Internal, External, Vendors, Personal) + action status (Needs Reply, Open Promise, FYI). No message from an unapproved sender is added to a contact timeline or an Open Promise.</div><div class="toolbar"><div class="tabs">${categoryOptions.map(t=>`<button class="tab ${ui.mailCategory===t?'active':''}" data-mail-cat="${t}">${t}</button>`).join('')}</div><label class="search">${icon('search')}<input id="mail-search" aria-label="Search emails" placeholder="Search messages..." value="${attr(ui.mailSearch)}"></label></div><div class="toolbar" style="margin-top:-8px"><div class="tabs">${actionOptions.map(t=>`<button class="tab ${ui.mailAction===t?'active':''}" data-mail-action="${t}">${t}</button>`).join('')}</div><span class="small muted">${mails.length} messages · demonstration only</span></div><div class="inbox-grid"><div class="card inbox-list"><div class="inbox-list-header"><strong>Organized conversations</strong><span class="small muted">${mails.length} displayed</span></div>${mails.length?mails.map(m=>`<button class="mail-row ${chosen?.id===m.id?'selected':''}" data-open-mail="${m.id}"><div class="line1"><strong>${esc(m.sender)}</strong><time>${esc(m.time||'Today')}</time></div><div class="company-name small" style="margin-top:4px;color:#526178">${esc(company(m.companyId)?.name|| (m.category==='Personal'?'PERSONAL / UNKNOWN':'NOT IN CONTACTS'))}</div><div class="subject">${esc(m.subject)}</div><div class="preview">${esc(m.preview)}</div><div class="line3">${messageCategories(m)}</div></button>`).join(''):itemEmpty('No emails match these filters.')}</div><div class="card detail-panel">${chosen?`<div class="detail-head"><div class="eyebrow">Conversation detail · ${esc(chosen.category)}</div><h2 style="font-size:20px;margin-top:7px">${esc(chosen.subject)}</h2><p class="small muted" style="margin-top:8px">${esc(chosen.sender)} · ${esc(chosen.email)} · ${esc(chosen.time||'Today')}</p><div class="pill-line">${messageCategories(chosen)}</div></div><div class="detail-body"><div class="block-title">Original message excerpt</div><p style="font-size:13px;line-height:1.7">${esc(chosen.body)}</p><hr class="divider"><div class="block-title">Relationship tracking status</div>${chosen.tracked?`<div class="notice" style="background:#eef7f1;border-color:#cfebda">${icon('shield')} <strong>Approved contact:</strong> ${esc(chosen.sender)}. Basic communication data can populate their LuMaCo record.${detailed(contact(chosen.contactId))?' Detailed relationship reporting is enabled.':''}</div><div class="btn-row" style="margin-top:11px">${button('View contact '+icon('arrow','sm'),'view-mail-contact','sm')}</div>`:`<div class="notice">${icon('lock')} <strong>Not tracked.</strong> This sender is not an approved LuMaCo contact. Sorting the message does not create a contact, timeline entry or promise. Personal messages are not used for contact suggestions by default.</div>`}<hr class="divider"><div class="block-title">AI insight · simulated</div>${chosen.tracked?`<p style="font-size:13px;line-height:1.7">${esc(chosen.action==='Open Promise'?'An existing commitment is mentioned and the customer is waiting for confirmation.':chosen.action==='Needs Reply'?'This message requests a response or review. It may require a next step.':'For reference; no immediate action detected.')}</p>`:'<p class="small muted">No relationship-level analysis performed. The message is only categorized for inbox organization.</p>'}${p?`<div class="note-box" style="margin-top:14px"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><strong>${icon('clipboard')} Open Promise automatically captured</strong>${promisePill(p)}</div><p style="margin-top:8px"><strong>${esc(p.title)}</strong></p><p>${esc(p.origin)}</p><div class="btn-row" style="margin-top:12px">${button('View / edit promise','view-mail-promise','sm')}${button('Complete','complete-mail-promise','sm')}</div></div>`:''}${chosen.tracked?`<hr class="divider"><div class="block-title">Conversation history</div><ul class="timeline">${(chosen.history||[]).map(h=>`<li><div class="t-time">${esc(h.when)}</div><p>${esc(h.text)}</p></li>`).join('')||'<li><p>No earlier conversation captured in this demo.</p></li>'}</ul>`:''}<hr class="divider"><div class="btn-row">${button(icon('link')+' Open original in email app','original-message','sm')}${chosen.tracked?button(icon('calendar')+' Log follow-up','mail-followup','sm'):''}</div><p class="small muted" style="margin-top:12px">No original account is connected. LuMaCo would deep-link to Outlook or Gmail after authorization; this demo does not open real mail.</p></div>`:itemEmpty('Select a message to explore its context.')}</div></div>`}
function contactRows(list,sel){return list.map(c=>`<button class="directory-entry ${sel===c.id?'selected':''}" data-open-contact="${c.id}"><div class="entry-head"><span class="avatar">${initials(c.name)}</span><div style="flex:1;min-width:0"><strong>${esc(c.name)} ${c.starred?`<span style="color:var(--gold)">${icon('star','sm')}</span>`:''}</strong><p>${esc(c.title)}</p></div>${icon('arrow','sm')}</div><div class="company-name contact-company-name" style="margin:9px 0 0 50px">${esc(company(c.companyId)?.name||'Unassigned')}</div><div class="entry-foot" style="margin-left:50px"><span class="pill ${c.priority==='High'?'gold':'neutral'}">${c.priority}</span>${detailed(c)?'<span class="pill blue">Detailed</span>':''}<span class="pill neutral">${esc((c.categories||[]).slice(0,2).join(', '))}</span></div></button>`).join('')}
function renderContacts(){let list=state.contacts.filter(c=>(ui.contactsFilter==='All'||(ui.contactsFilter==='Starred'&&c.starred)||(ui.contactsFilter==='Detailed'&&detailed(c))||(ui.contactsFilter==='High priority'&&c.priority==='High'))&&(!ui.contactSearch||`${c.name} ${c.title} ${c.email} ${company(c.companyId)?.name} ${c.categories.join(' ')}`.toLowerCase().includes(ui.contactSearch.toLowerCase())));let c=state.contacts.find(c=>c.id===ui.selectedContact)||list[0];if(c&&!list.includes(c))c=list[0];return `${head('Contact intelligence','Contacts','All approved contacts get basic tracking. Starred and manually selected contacts get detailed reports.',button(icon('plus')+' Add contact','add-contact','gold'))}<div class="toolbar"><div class="tabs">${['All','Starred','Detailed','High priority'].map(x=>`<button class="tab ${ui.contactsFilter===x?'active':''}" data-contact-filter="${x}">${x}</button>`).join('')}</div><label class="search">${icon('search')}<input id="contact-search" placeholder="Search contacts..." value="${attr(ui.contactSearch)}"></label></div><div class="directory-grid"><div class="card directory-list"><div class="inbox-list-header"><strong>${list.length} approved contacts</strong><span class="small muted">No automatic enrollment</span></div>${list.length?contactRows(list,c?.id):itemEmpty('No contacts match. Add a new one to begin.')}</div><div class="card">${c?renderContactDetail(c):itemEmpty('Choose a contact to view their relationship.')}</div></div>`}
function renderContactDetail(c){let co=company(c.companyId),prom=state.promises.filter(p=>p.contactId===c.id&&p.status==='Open'),int=state.interactions.filter(i=>i.contactId===c.id).sort((a,b)=>b.date.localeCompare(a.date)),msgs=state.messages.filter(m=>m.contactId===c.id);return `<div class="profile-head"><div class="eyebrow">Contact profile · Approved for basic tracking</div><div class="big-company contact-company-name">${esc(co?.name||'No company')}</div><div class="person-line"><span class="avatar">${initials(c.name)}</span><div style="flex:1"><h2>${esc(c.name)}</h2><p class="role">${esc(c.title)} · ${esc(relLabel(c))}</p></div><button class="star-button ${c.starred?'on':''}" title="Star / unstar" data-star="${c.id}">${icon('star')}</button></div><div class="btn-row" style="margin-top:18px">${button(icon('edit')+' Edit contact','edit-current-contact','sm')}${button(icon('phone')+' Simulate call','call-current-contact','sm')}${button(icon('file')+' Add note','note-current-contact','sm')}</div></div><div class="profile-section"><div class="info-grid"><div class="info-cell"><label>Priority</label><strong>${esc(c.priority)}</strong></div><div class="info-cell"><label>Detailed reports</label><strong>${detailed(c)?'Enabled':'Standard tracking only'}</strong></div><div class="info-cell"><label>Follow-up rhythm</label><strong>${esc(c.cadence)} days</strong></div><div class="info-cell"><label>Next follow-up</label><strong>${dueText(nextFollow(c))}</strong></div></div><label class="checkline"><input type="checkbox" data-detail-toggle="${c.id}" ${c.detail?'checked':''} ${c.starred?'disabled':''}> <span>${c.starred?'Detailed reports are enabled automatically while starred.':'Enable detailed reports without starring this contact.'}</span></label>${c.notes?`<p class="small muted" style="margin-top:8px">${esc(c.notes)}</p>`:''}<div class="pill-line">${(c.categories||[]).map(x=>`<span class="pill blue">${esc(x)}</span>`).join('')}</div></div><div class="profile-section"><div class="section-title"><h2>${icon('clipboard')} Open Promises</h2></div>${prom.length?prom.map(p=>`<div class="item-row"><div class="row-main"><strong>${esc(p.title)}</strong><p>${esc(p.owner)} · ${esc(p.source)}</p><div class="row-meta">${promisePill(p)}</div></div><button data-open-promise="${p.id}" class="row-arrow">${icon('arrow')}</button></div>`).join(''):itemEmpty('No open promises linked to this contact.')}</div><div class="profile-section"><div class="section-title"><h2>${icon('clock')} Relationship timeline</h2></div>${int.slice(0,detailed(c)?8:4).map(i=>`<div class="item-row"><div class="row-icon">${icon(i.type==='Call'?'phone':i.type==='Meeting'?'calendar':i.type==='Email'?'mail':'file')}</div><div class="row-main"><strong>${esc(i.title)}</strong><p>${dateNice(i.date)} · ${esc(i.source)}</p><p>${esc(i.summary)}</p></div></div>`).join('')||itemEmpty('No interactions saved yet.')}${msgs.length?`<p class="small muted" style="margin-top:12px">${msgs.length} matching inbox message(s) · ${detailed(c)?'Detailed reporting enabled':'Basic metadata tracked'}</p>`:''}</div><div class="profile-section"><div class="section-title"><h2>${icon('building')} Contact information</h2></div><div class="simple-list"><div class="event">${icon('mail')}<div><strong>${esc(c.email||'No email')}</strong><p>Email address</p></div></div><div class="event">${icon('phone')}<div><strong>${esc(c.phone||'No phone')}</strong><p>Telephone</p></div></div></div></div>`}
function renderCompanies(){let co=company(ui.selectedCompany)||state.companies[0];let list=state.companies;let contacts=state.contacts.filter(c=>c.companyId===co?.id),projs=state.projects.filter(p=>p.companyId===co?.id),open=state.promises.filter(p=>p.companyId===co?.id&&p.status==='Open');return `${head('Account relationships','Companies','Company is the primary organizing label. See people, promises, projects and activity together.',button(icon('plus')+' Add company','add-company','gold'))}<div class="directory-grid"><div class="card directory-list"><div class="inbox-list-header"><strong>Companies</strong><span class="small muted">${list.length} organizations</span></div>${list.map(c=>`<button class="directory-entry ${co?.id===c.id?'selected':''}" data-open-company="${c.id}"><div class="entry-head"><span class="avatar">${icon('building')}</span><div style="flex:1"><strong style="font-size:13px;text-transform:uppercase">${esc(c.name)}</strong><p>${esc(c.type)}</p></div>${icon('arrow','sm')}</div><div class="entry-foot" style="margin-left:50px"><span class="pill neutral">${state.contacts.filter(x=>x.companyId===c.id).length} people</span><span class="pill neutral">${state.projects.filter(x=>x.companyId===c.id).length} projects</span></div></button>`).join('')}</div><div class="card">${co?`<div class="profile-head"><div class="eyebrow">Company profile · ${esc(co.type)}</div><div class="big-company" style="font-size:28px;margin-top:9px">${esc(co.name)}</div><p class="muted small" style="margin-top:10px">${esc(co.notes||'No company notes')}</p><div class="grid g3" style="margin-top:18px;gap:9px">${[['Contacts',contacts.length],['Projects',projs.length],['Open promises',open.length]].map(x=>`<div class="info-cell"><label>${x[0]}</label><strong style="font-size:20px">${x[1]}</strong></div>`).join('')}</div></div><div class="profile-section"><div class="section-title"><h2>${icon('users')} People at ${esc(co.name)}</h2></div>${contacts.length?contacts.map(c=>`<div class="item-row"><div class="avatar">${initials(c.name)}</div><div class="row-main"><strong>${esc(c.name)}</strong><p>${esc(c.title)} · ${esc(c.priority)} priority</p><div class="row-meta">${detailed(c)?'<span class="pill gold">Detailed</span>':'<span class="pill neutral">Standard</span>'}</div></div><button class="row-arrow" data-open-contact="${c.id}">${icon('arrow')}</button></div>`).join(''):itemEmpty('No approved contacts at this company.')}</div><div class="profile-section"><div class="section-title"><h2>${icon('briefcase')} Projects</h2></div>${projs.length?projs.map(p=>`<div class="item-row"><div class="row-main"><strong>${esc(p.name)}</strong><p>${esc(p.description)}</p><div class="row-meta"><span class="pill blue">${esc(p.status)}</span></div></div><button class="row-arrow" data-open-project="${p.id}">${icon('arrow')}</button></div>`).join(''):itemEmpty('No linked projects.')}</div><div class="profile-section"><div class="section-title"><h2>${icon('clipboard')} Open Promises</h2></div>${open.length?open.map(p=>`<div class="item-row"><div class="row-main"><strong>${esc(p.title)}</strong><p>${esc(p.owner)} · ${esc(contact(p.contactId)?.name||'')}</p></div>${promisePill(p)}<button class="row-arrow" data-open-promise="${p.id}">${icon('arrow')}</button></div>`).join(''):itemEmpty('No open promises.')}</div>`:''}</div></div>`}
function renderProjects(){let p=state.projects.find(p=>p.id===ui.selectedProject)||state.projects[0];let co=company(p?.companyId),prom=state.promises.filter(x=>x.projectId===p?.id&&x.status==='Open'),int=state.interactions.filter(x=>x.projectId===p?.id);return `${head('Project context','Projects','Pull relevant contact, commitment and communication context into one sourced view.',button(icon('plus')+' Add project','add-project','gold'))}<div class="directory-grid"><div class="project-list">${state.projects.map(x=>`<button class="project" style="text-align:left;${p?.id===x.id?'border-color:var(--gold);box-shadow:inset 3px 0 0 var(--gold)':''}" data-open-project="${x.id}"><div class="company-name">${esc(company(x.companyId)?.name||'Unassigned')}</div><h3 style="margin-top:5px">${esc(x.name)}</h3><p>${esc(x.description)}</p><div class="pill-line"><span class="pill ${x.status==='At risk'?'danger':'neutral'}">${esc(x.status)}</span><span class="pill blue">${x.progress}% complete</span></div><div class="progress"><b style="width:${Math.max(0,Math.min(100,x.progress))}%"></b></div></button>`).join('')}</div><div class="card">${p?`<div class="profile-head"><div class="eyebrow">Project · ${esc(p.status)}</div><div class="big-company">${esc(co?.name||'No company')}</div><h2 style="font-size:22px;margin-top:8px">${esc(p.name)}</h2><p class="small muted" style="margin-top:10px">${esc(p.description)}</p><div class="progress"><b style="width:${p.progress}%"></b></div><p class="small muted" style="margin-top:7px">${p.progress}% progress · fictional sample</p></div><div class="profile-section"><div class="section-title"><h2>${icon('users')} Project contacts</h2></div>${p.contactIds.map(id=>{let c=contact(id);return c?`<div class="item-row"><div class="row-main"><strong>${esc(c.name)}</strong><p>${esc(company(c.companyId)?.name||'')} · ${esc(c.title)}</p></div><button class="row-arrow" data-open-contact="${c.id}">${icon('arrow')}</button></div>`:''}).join('')||itemEmpty('No people linked.')}</div><div class="profile-section"><div class="section-title"><h2>${icon('clipboard')} Commitments and decisions</h2></div>${prom.length?prom.map(q=>`<div class="item-row"><div class="row-main"><strong>${esc(q.title)}</strong><p>${esc(q.source)}</p><div class="row-meta">${promisePill(q)}</div></div><button class="row-arrow" data-open-promise="${q.id}">${icon('arrow')}</button></div>`).join(''):itemEmpty('No open promises associated with this project.')}</div><div class="profile-section"><div class="section-title"><h2>${icon('clock')} Source-based activity</h2></div>${int.map(x=>`<div class="item-row"><div class="row-icon">${icon('file')}</div><div class="row-main"><strong>${esc(x.title)}</strong><p>${esc(x.summary)}</p><p>${dateNice(x.date)} · Source: ${esc(x.source)}</p></div></div>`).join('')||itemEmpty('No logged project activity.')}</div>`:''}</div></div>`}
function renderPromises(){let all=state.promises.filter(p=>ui.promiseFilter==='All'||p.status===ui.promiseFilter||(ui.promiseFilter==='Overdue'&&p.status==='Open'&&dayDiff(p.due)<0)||(ui.promiseFilter==='Made by me'&&p.status==='Open'&&p.direction==='Made by me')||(ui.promiseFilter==='Made to me'&&p.status==='Open'&&p.direction==='Made to me')).sort((a,b)=>a.due.localeCompare(b.due));return `${head('Commitment intelligence','Open Promises','Automatically captured commitments, with visible sources, owners and due dates.',button(icon('plus')+' Add promise','add-promise','gold'))}<div class="toolbar"><div class="tabs">${['Open','Overdue','Made by me','Made to me','Completed','Dismissed','All'].map(t=>`<button class="tab ${ui.promiseFilter===t?'active':''}" data-promise-filter="${t}">${t}</button>`).join('')}</div><span class="small muted">Auto-created promises can always be edited, completed or dismissed.</span></div><div class="grid g2">${all.map(p=>`<div class="card pad"><div style="display:flex;align-items:center;justify-content:space-between;gap:8px"><span class="company-name">${esc(company(p.companyId)?.name||'No company')}</span>${promisePill(p)}</div><h2 style="margin:12px 0 6px;font-size:17px">${esc(p.title)}</h2><p class="small muted">${esc(contact(p.contactId)?.name||'Unknown person')} · ${esc(p.direction)} · Responsible: ${esc(p.owner)}</p><div class="note-box" style="margin-top:13px;background:#f9fafb;border-color:var(--line)"><strong class="small">Original source</strong><p style="margin-top:4px">${esc(p.source)}</p><p style="margin-top:6px;font-style:italic">“${esc(p.origin)}”</p></div><div class="btn-row" style="margin-top:13px">${button(icon('edit')+' Review / Edit','edit-promise-'+p.id,'sm')}${p.status==='Open'?button(icon('check')+' Complete','complete-promise-'+p.id,'sm primary')+button('Dismiss','dismiss-promise-'+p.id,'sm danger'):''}</div></div>`).join('')||`<div class="card" style="grid-column:1/-1">${itemEmpty('No promises in this category.')}</div>`}</div>`}
function renderFollowups(){let contacts=[...state.contacts].filter(c=>c.cadence).sort((a,b)=>nextFollow(a).localeCompare(nextFollow(b)));return `${head('Relationship maintenance','Follow-ups','Schedule meaningful touchpoints without manually creating every reminder.',button(icon('plus')+' Log touchpoint','log-touchpoint','gold'))}<div class="grid g3" style="margin-bottom:19px">${[['Overdue',contacts.filter(c=>dayDiff(nextFollow(c))<0).length,'alert'],['Due this week',contacts.filter(c=>dayDiff(nextFollow(c))>=0&&dayDiff(nextFollow(c))<=7).length,'calendar'],['Scheduled relationships',contacts.length,'users']].map(([n,v,i])=>`<div class="card summary-stat"><div class="stat-icon">${icon(i)}</div><strong>${v}</strong><span>${n}</span></div>`).join('')}</div><div class="card pad">${section(`${icon('calendar')} Your follow-up queue`)}${contacts.map(c=>`<div class="item-row"><div class="row-icon">${icon('users')}</div><div class="row-main"><strong>${esc(c.name)}</strong><p><b class="company-name">${esc(company(c.companyId)?.name||'')}</b> · Every ${c.cadence} days</p><div class="row-meta"><span class="pill ${dayDiff(nextFollow(c))<0?'danger':dayDiff(nextFollow(c))<=7?'gold':'neutral'}">${dueText(nextFollow(c))}</span>${detailed(c)?'<span class="pill blue">Detailed</span>':''}</div></div><div class="btn-row">${button('Log contact','log-'+c.id,'sm')}${button('View','view-'+c.id,'sm')}</div></div>`).join('')}</div>`}
function renderSuggestions(){return `${head('Contact discovery','Suggested Contacts','LuMaCo can suggest frequent business contacts, but never enrolls or tracks them without approval.',button(icon('plus')+' Add contact manually','add-contact','gold'))}<div class="notice" style="margin-bottom:19px">${icon('shield')} <strong>Privacy rule:</strong> Personal or unknown senders are not converted into tracked contacts. Suggestions are optional and should use limited metadata; people become tracked only after you explicitly add them.</div>${!state.settings.suggestions?`<div class="card pad">Suggested Contacts are disabled in Settings. ${button('Open settings','go-settings','sm')}</div>`:`<div class="grid g2">${state.suggestions.map(s=>`<div class="card pad"><div class="entry-head"><span class="avatar">${initials(s.name)}</span><div><h2 style="font-size:17px">${esc(s.name)}</h2><div class="small muted">${esc(s.title)}</div></div></div><div class="company-name" style="margin:13px 0 9px">${esc(s.company)}</div><p class="small muted">${esc(s.email)}</p><div class="note-box" style="margin:13px 0"><p><strong>Why suggested?</strong> ${esc(s.reason)}</p><p style="margin-top:5px">Not tracked · Awaiting your approval</p></div><div class="btn-row">${button(icon('plus')+' Review & add','approve-suggest-'+s.id,'sm primary')}${button('Dismiss','dismiss-suggest-'+s.id,'sm')}</div></div>`).join('')||`<div class="card" style="grid-column:1/-1">${itemEmpty('No suggestions awaiting review.')}</div>`}</div>`}`}
function renderIntegrations(){const integrations=[['Microsoft Outlook','mail','Email changes, thread context and link-backs'],['Gmail','mail','Email conversation categorization and summaries'],['Microsoft / Google Calendar','calendar','Scheduled meetings and completed meeting prompts'],['Phone calls','phone','Call-ended triggers and call metadata; requires platform-specific support'],['SMS / messaging','message','Message metadata where device/platform permissions allow'],['Project tools / CRM','briefcase','Optional sourced project data without replacing existing systems']];return `${head('Read-only first','Integrations','Connect the tools professionals already use. In this prototype, every integration is simulated.')}<div class="notice" style="margin-bottom:19px"><strong>Current status: no live account access.</strong> These are capability previews, not authenticated connections. Browser-based apps cannot scrape arbitrary device SMS, call logs, or iMessage. Production access depends on provider APIs, operating-system permissions, consent, and employer policies.</div><div class="grid g3">${integrations.map(([name,i,descr])=>`<div class="integration">${icon(i,'lg')}<strong>${name}</strong><p>${descr}</p><div class="pill-line" style="margin:15px 0"><span class="pill neutral">Not connected</span><span class="pill gold">Simulation available</span></div>${button('Preview workflow','preview-integration-'+name.replaceAll(' ','_'),'sm')}</div>`).join('')}</div><div class="card pad gap-section"><h2 style="margin-bottom:12px">How information reaches LuMaCo</h2><div class="grid g3"><div class="note-box"><strong>1. Authorized read access</strong><p style="margin-top:7px">Account owner grants narrowly scoped access. Data is pulled through approved APIs or supported device integrations.</p></div><div class="note-box"><strong>2. Match approved contacts</strong><p style="margin-top:7px">Emails sorted for everyone. Only approved contacts receive relationship histories and promises.</p></div><div class="note-box"><strong>3. Review and surface actions</strong><p style="margin-top:7px">Create Open Promises automatically; ask for review on detailed notes, mismatches, conflicts, and uncertain data.</p></div></div><p class="muted small" style="margin-top:16px">Personal storage in a real product would require authenticated accounts, encryption, retention rules, and an independent backend. Local demo browser storage does not provide these safeguards.</p></div>`}
function renderSettings(){return `${head('Workspace preferences','Settings','Control privacy, automation visibility and your local demo data.')}<div class="card pad"><h2 style="margin-bottom:5px">Privacy & automation</h2><div class="settings-row"><div><strong>Suggested Contacts</strong><p>Offer frequent business contacts for approval without automatically tracking them.</p></div><button class="switch ${state.settings.suggestions?'on':''}" data-toggle-setting="suggestions" role="switch" aria-checked="${state.settings.suggestions}" aria-label="Suggested contacts"></button></div><div class="settings-row"><div><strong>Automatic Open Promise detection</strong><p>When an approved contact makes a clear commitment, add it automatically. Every promise keeps its source and can be edited or dismissed.</p></div><button class="switch ${state.settings.autoPromises?'on':''}" data-toggle-setting="autoPromises" role="switch" aria-checked="${state.settings.autoPromises}" aria-label="Automatic promises"></button></div><div class="settings-row"><div><strong>Work / Focus Mode</strong><p>Pause in-app reminders visually. This standalone webpage cannot silence Outlook, phone calls, or system notifications.</p></div><button class="switch ${state.settings.focus?'on':''}" data-toggle-setting="focus" role="switch" aria-checked="${state.settings.focus}" aria-label="Focus mode"></button></div><div class="settings-row"><div><strong>Personal workspace</strong><p>Your prototype data is stored only in this browser's local storage, if available. It is not password protected, synchronized, or guaranteed private on shared devices.</p></div><span class="pill gold">Local demo</span></div></div><div class="card pad gap-section"><h2>Relationship tracking rules</h2><div class="grid g3" style="margin-top:15px"><div class="note-box"><strong>Basic tracking</strong><p style="margin-top:5px">Every explicitly approved LuMaCo contact.</p></div><div class="note-box"><strong>Detailed reporting</strong><p style="margin-top:5px">Automatically on for starred contacts; optional manual override for others.</p></div><div class="note-box"><strong>Unapproved senders</strong><p style="margin-top:5px">Categorized for Smart Email, never logged to relationship histories.</p></div></div><p class="muted small" style="margin-top:12px">Custom contact categories: ${state.categories.map(x=>esc(x)).join(' · ')}</p></div><div class="card pad gap-section"><h2>Demo data management</h2><p class="muted small" style="margin:7px 0 17px">Explore freely. You can export your current demo state, restore a JSON export, or reset fictional data.</p><div class="btn-row">${button(icon('download')+' Export demo JSON','export-demo','sm')}${button(icon('upload')+' Import demo JSON','import-demo','sm')}${button(icon('refresh')+' Reset fictional demo','reset-demo','sm danger')}</div><input type="file" id="import-file" accept="application/json,.json" style="display:none"></div><div class="card pad gap-section"><h2>Design system</h2><p class="muted small" style="margin:7px 0 12px">Approved: Navy & Champagne Gold · white dashboard · balanced density · original prototype-inspired review flows.</p><div style="display:flex;gap:8px">${['#172c47','#b58a3b','#ffffff','#f5f7fa','#e3e8ef'].map(x=>`<span title="${x}" style="width:58px;height:37px;border-radius:8px;background:${x};border:1px solid #ddd"></span>`).join('')}</div></div>`}
function openModal(kind,data=null){ui.modal=kind;ui.modalData=data;ui.meetingStage='choose';ui.meetingRecorded=false;ui.meetingConsent=false;renderModal()}
function closeModal(){ui.modal=null;ui.modalData=null;renderModal()}
function wrapModal(title,subtitle,body,foot='',wide=false){return `<div class="modal-backdrop" data-dismiss="true"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${attr(title)}"><header class="modal-header"><div><div class="eyebrow">${esc(subtitle)}</div><h2>${esc(title)}</h2></div><button class="close" aria-label="Close dialog" data-action="close-modal">${icon('close','lg')}</button></header>${body}<footer class="modal-footer">${foot||button('Close','close-modal')}</footer></section></div>`}
function renderModal(){const dest=document.getElementById('overlay');if(!ui.modal){dest.innerHTML='';return}let h='',body='',foot='';let c,d,p,co;switch(ui.modal){
case 'scenarios':h='Demonstrate automation';body=`<div class="modal-body"><div class="demo-disclaimer">${icon('shield')} All workflows are fictional simulations. No apps, phone logs, microphone, calendar or inbox are connected.</div><div class="grid" style="gap:11px">${[['mail','Incoming customer email','Automatic categorization, contact match, Open Promise and email history.','simulate-email'],['message','Incoming customer text','Simulate a matched, permitted text and an automatically identified promise.','simulate-text'],['phone','Completed customer call','An immediate personal note pop-up for a detailed contact.','simulate-call'],['mic','Meeting ends','Choose a simulated meeting recording or after-meeting recap.','simulate-meeting'],['users','Suggested Contacts','Review a frequent business contact before tracking begins.','go-suggested']].map(([ico,t,sub,a])=>`<button class="card pad" style="width:100%;display:flex;align-items:center;gap:14px;text-align:left" data-action="${a}"><span class="row-icon">${icon(ico)}</span><span style="flex:1"><strong>${t}</strong><span class="small muted" style="display:block;margin-top:3px">${sub}</span></span>${icon('arrow')}</button>`).join('')}</div></div>`;break;
case 'contact':c=ui.modalData?.id?contact(ui.modalData.id):null;d=ui.modalData?.suggestion||{};h=c?'Edit contact':'Add an approved contact';body=`<form id="contact-form" class="modal-body"><div class="demo-disclaimer">A contact starts basic automatic tracking only after you save it. Starred contacts automatically have detailed reporting; additional contacts may opt in manually.</div><div class="fields2"><label class="field"><span>Full name *</span><input name="name" required maxlength="90" value="${attr(c?.name||d.name||'')}" placeholder="Full name"></label><label class="field"><span>Job title</span><input name="title" maxlength="90" value="${attr(c?.title||d.title||'')}" placeholder="Project manager"></label><label class="field"><span>Email address</span><input name="email" type="email" value="${attr(c?.email||d.email||'')}" placeholder="name@company.com"></label><label class="field"><span>Phone number</span><input name="phone" value="${attr(c?.phone||'')}" placeholder="(402) 555-0100"></label><label class="field"><span>Existing company</span><select name="companyId"><option value="">Choose / create below</option>${state.companies.map(x=>`<option value="${x.id}" ${c?.companyId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field"><span>New company name (optional)</span><input name="newCompany" value="${attr(!c&&d.company||'')}" placeholder="Create a new company"></label><label class="field"><span>Priority</span><select name="priority">${['High','Medium','Low'].map(x=>`<option ${c?.priority===x?'selected':!c&&x==='Medium'?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>How often should you reach out?</span><select name="cadence">${[['7','Weekly'],['14','Every 2 weeks'],['30','Monthly'],['90','Quarterly'],['180','Every 6 months'],['365','Annually']].map(([v,t])=>`<option value="${v}" ${(c?.cadence||90)==v?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="field"><span>Contact categories (select multiple)</span><div class="choice-chips">${state.categories.map(x=>`<label><input type="checkbox" name="category" value="${attr(x)}" ${c?.categories?.includes(x)||(!c&&d.category===x)?'checked':''}> ${esc(x)}</label>`).join('')}</div></label><label class="field"><span>Add a custom category (available to everyone afterward)</span><input name="newCategory" maxlength="45" placeholder="e.g. Architect, Distributor, Consultant"></label><div class="grid g2" style="gap:6px"><label class="checkline"><input type="checkbox" name="starred" ${c?.starred?'checked':''}><span>Starred relationship<br><span class="small muted">Automatically enables detailed reports</span></span></label><label class="checkline"><input type="checkbox" name="detail" ${c?.detail?'checked':''}><span>Detailed reports independently<br><span class="small muted">For an unstarred contact, too</span></span></label></div><label class="field"><span>Private relationship notes</span><textarea name="notes" placeholder="Helpful context and preferences">${esc(c?.notes||'')}</textarea></label></form>`;foot=`${button('Cancel','close-modal') }<button class="btn primary" type="submit" form="contact-form">${c?'Save changes':'Approve & add contact'}</button>`;break;
case 'company':h='Add company';body=`<form id="company-form" class="modal-body"><label class="field"><span>Company name *</span><input name="name" required maxlength="100" placeholder="Organization name"></label><label class="field"><span>Company category</span><select name="type">${['Contractor','Engineer','Vendor','Owner','Internal','Other'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field"><span>Notes</span><textarea name="notes" placeholder="Optional context"></textarea></label></form>`;foot=`${button('Cancel','close-modal')}<button type="submit" form="company-form" class="btn primary">Save company</button>`;break;
case 'project':h='Add project';body=`<form id="project-form" class="modal-body"><label class="field"><span>Project name *</span><input name="name" required maxlength="110" placeholder="Project title"></label><label class="field"><span>Company</span><select name="companyId">${state.companies.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><div class="fields2"><label class="field"><span>Status</span><select name="status">${['Planning','Active','At risk','Completed'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field"><span>Progress percent</span><input name="progress" type="number" min="0" max="100" value="0"></label></div><label class="field"><span>Description</span><textarea name="description"></textarea></label><label class="field"><span>Linked contacts</span><div class="choice-chips">${state.contacts.map(x=>`<label><input type="checkbox" name="contactIds" value="${x.id}"> ${esc(x.name)}</label>`).join('')}</div></label></form>`;foot=`${button('Cancel','close-modal')}<button type="submit" form="project-form" class="btn primary">Create project</button>`;break;
case 'promise':p=ui.modalData?.id?state.promises.find(x=>x.id===ui.modalData.id):null;h=p?'Review Open Promise':'Add Open Promise';body=`<form id="promise-form" class="modal-body"><div class="demo-disclaimer">${icon('clipboard')} ${p?`Detected or entered from: ${esc(p.source)}. Changes do not modify the original communication.`:'Add a commitment to your personal workspace.'}</div><label class="field"><span>Promise / commitment *</span><input required name="title" value="${attr(p?.title||'')}" maxlength="160" placeholder="Send updated drawings"></label><div class="fields2"><label class="field"><span>Linked contact</span><select name="contactId"><option value="">None</option>${state.contacts.map(c=>`<option value="${c.id}" ${p?.contactId===c.id?'selected':''}>${esc(c.name)} — ${esc(company(c.companyId)?.name||'')}</option>`).join('')}</select></label><label class="field"><span>Who is responsible?</span><input name="owner" value="${attr(p?.owner||'You')}" required></label><label class="field"><span>Due date</span><input type="date" name="due" value="${attr(p?.due||days(3))}" required></label><label class="field"><span>Direction</span><select name="direction">${['Made by me','Made to me'].map(x=>`<option ${p?.direction===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field"><span>Source</span><input name="source" value="${attr(p?.source||'Manual note')}" placeholder="Email, meeting, call, manual"></label><label class="field"><span>Original supporting context</span><textarea name="origin">${esc(p?.origin||'')}</textarea></label></form>`;foot=`${button('Cancel','close-modal')}<button type="submit" form="promise-form" class="btn primary">${p?'Save changes':'Create promise'}</button>`;break;
case 'call':c=contact(ui.modalData?.contactId)||state.contacts.find(detailed)||state.contacts[0];co=company(c.companyId);h='Call ended · Review touchpoint';body=`<form id="call-form" class="modal-body"><div class="steps"><span class="step on">1 · Call ended</span> ${icon('arrow','sm')} <span class="step on">2 · Add context</span> ${icon('arrow','sm')} <span class="step">3 · Save timeline</span></div><div class="demo-disclaimer"><strong>SIMULATED CALL-END TRIGGER.</strong> A real phone integration has not been installed. LuMaCo only knows call metadata here; it cannot infer what was said without a recording, transcription, or your notes.</div><div class="card pad" style="box-shadow:none;margin-bottom:18px"><div class="eyebrow">${esc(co?.name||'Company')}</div><div style="display:flex;gap:12px;align-items:center;margin-top:9px"><div class="avatar">${initials(c.name)}</div><div><h2>${esc(c.name)}</h2><p class="small muted">Call ended · Today · 12 min 18 sec · Detailed relationship</p></div></div></div><label class="field"><span>What did you discuss? *</span><textarea name="summary" required placeholder="Summarize the conversation, important details and context..."></textarea></label><label class="field"><span>Next step / follow-up (optional)</span><input name="next" placeholder="e.g. Confirm material availability"></label><div class="fields2"><label class="field"><span>Open Promise (optional)</span><input name="promise" placeholder="e.g. Send revised proposal"></label><label class="field"><span>Promise due date</span><input name="due" type="date" value="${days(3)}"></label></div><div class="notice">This review saves text only to your personal contact timeline. No raw call audio is created or retained by this demo.</div></form>`;foot=`${button('Remind me later','call-later')}${button('Discard','close-modal','danger')}<button type="submit" form="call-form" class="btn primary">Save to contact history</button>`;break;
case 'meeting':c=contact(ui.modalData?.contactId)||state.contacts.find(detailed)||state.contacts[0];co=company(c.companyId);h='Meeting ended · Capture the next step';if(ui.meetingStage==='choose'){body=`<div class="modal-body"><div class="steps"><span class="step on">1 · Capture</span> ${icon('arrow','sm')} <span class="step">2 · Review transcript</span> ${icon('arrow','sm')} <span class="step">3 · File as text</span></div><div class="demo-disclaimer"><strong>SIMULATED MEETING EVENT.</strong> Neither microphone nor calendar is connected. Live meeting recording would require clear participant consent and a permitted capture method.</div><div class="card pad" style="box-shadow:none;margin-bottom:17px"><div class="company-name">${esc(co?.name||'Company')}</div><h2 style="margin-top:7px">Project check-in with ${esc(c.name)}</h2><p class="small muted" style="margin-top:5px">Today · Scheduled meeting with a detailed contact</p></div><div class="grid g2"><button class="card pad" data-action="meeting-live" style="text-align:left"><div class="row-icon" style="margin-bottom:11px">${icon('mic')}</div><h3>Record meeting</h3><p class="small muted" style="margin-top:6px">With participant consent. Demo recording/transcript will be simulated.</p></button><button class="card pad" data-action="meeting-recap" style="text-align:left"><div class="row-icon" style="margin-bottom:11px">${icon('message')}</div><h3>Record a recap afterward</h3><p class="small muted" style="margin-top:6px">A short verbal recap to turn into a text note; demo transcription simulated.</p></button></div></div>`;foot=button('Not now','close-modal');}else if(ui.meetingStage==='record'){body=`<div class="modal-body"><div class="steps"><span class="step on">1 · Capture</span> ${icon('arrow','sm')} <span class="step">2 · Review transcript</span> ${icon('arrow','sm')} <span class="step">3 · File as text</span></div><div class="demo-disclaimer">The controls below <strong>simulate</strong> recording and transcription. No microphone access, audio capture, or real transcription happens in this prototype.</div><div class="card pad" style="text-align:center;box-shadow:none"><div class="eyebrow">${ui.meetingKind==='live'?'Live meeting demo':'After-meeting voice recap demo'}</div><div style="width:86px;height:86px;border:2px solid var(--gold);border-radius:50%;display:grid;place-items:center;margin:22px auto;background:#faf6ed;color:var(--gold)">${icon(ui.meetingRecorded?'checkcircle':'mic','lg')}</div><h2>${ui.meetingRecorded?'Sample recording complete':'Ready to simulate recording'}</h2><p class="small muted" style="margin-top:7px">${ui.meetingRecorded?'A fictional transcript is ready to review.':'No audio is being captured.'}</p>${ui.meetingKind==='live'?`<label class="checkline" style="justify-content:center;margin-top:16px"><input id="meeting-consent" type="checkbox" ${ui.meetingConsent?'checked':''}> <span>I would obtain consent from meeting participants.</span></label>`:''}<div class="btn-row" style="justify-content:center;margin-top:16px">${ui.meetingRecorded?button('Review sample transcript '+icon('arrow','sm'),'meeting-review','primary'):button(icon('mic')+' Simulate start / stop','meeting-capture','gold')}</div></div></div>`;foot=button('Back','meeting-back');}else{body=`<form id="meeting-form" class="modal-body"><div class="steps"><span class="step">1 · Capture</span> ${icon('arrow','sm')} <span class="step on">2 · Review transcript</span> ${icon('arrow','sm')} <span class="step">3 · File as text</span></div><div class="demo-disclaimer"><strong>Fictional transcript provided for demonstration.</strong> No real voice was recorded, processed, or stored. Edit and approve the text before filing it.</div><label class="field"><span>Transcribed meeting note</span><textarea name="transcript" style="min-height:140px">We reviewed the Riverside mechanical drawing changes. Sarah asked for the updated package before the end of the week. I said I would send the revised drawings Friday. We should check equipment clearances before sending.</textarea></label><label class="field"><span>Summary for customer timeline</span><textarea name="summary">Reviewed Riverside drawing revisions and equipment clearances. Next step: send updated drawings by Friday.</textarea></label><div class="fields2"><label class="field"><span>Extracted Open Promise</span><input name="promise" value="Send updated Riverside drawings"></label><label class="field"><span>Due date</span><input name="due" type="date" value="${days(2)}"></label></div><div class="notice">Saving files the approved text to the personal contact history and creates the commitment. In production, temporary audio would be deleted after transcription unless the user explicitly opts to retain it.</div></form>`;foot=`${button('Back','meeting-record-back')}<button class="btn primary" type="submit" form="meeting-form">Approve & save text</button>`;}break;
case 'note':c=contact(ui.modalData?.contactId)||state.contacts[0];h='Log a touchpoint';body=`<form class="modal-body" id="note-form"><div class="company-name" style="margin-bottom:13px">${esc(company(c.companyId)?.name||'')}</div><label class="field"><span>Contact</span><select name="contactId">${state.contacts.map(q=>`<option value="${q.id}" ${q.id===c.id?'selected':''}>${esc(q.name)} — ${esc(company(q.companyId)?.name||'')}</option>`).join('')}</select></label><label class="field"><span>Type</span><select name="type"><option>Call</option><option>Meeting</option><option>Text</option><option>Other</option></select></label><label class="field"><span>Conversation notes *</span><textarea name="summary" required placeholder="What happened?"></textarea></label><label class="checkline"><input type="checkbox" name="updateLast" checked><span>Update date of last meaningful contact and next-follow-up schedule.</span></label></form>`;foot=`${button('Cancel','close-modal')}<button type="submit" class="btn primary" form="note-form">Save touchpoint</button>`;break;
case 'reset':h='Reset the fictional demo?';body=`<div class="modal-body"><p>Resetting will erase changes you've made to this demo in this browser and restore the original example contacts, promises, emails and projects.</p><p class="muted small" style="margin-top:9px">Export JSON first if you want a copy of your changes.</p></div>`;foot=`${button('Cancel','close-modal')}${button('Reset all sample data','confirm-reset','danger')}`;break;
}
dest.innerHTML=wrapModal(h,'LuMaCo · Interactive prototype',body,foot,ui.modal==='contact'||ui.modal==='meeting');}
